"""Deterministic compactor for generated OpenAPI TypeScript definitions.

Replaces repetitive OpenAPI boilerplate (JSDoc copies, empty parameter maps,
uniform HTTP error envelopes, and standard operation/list envelopes) with
reusable TypeScript generic aliases that preserve exact type equivalence.
"""

from __future__ import annotations

import re
import sys
from collections.abc import Sequence
from pathlib import Path

_BANNER = (
    "/**\n"
    " * This file was auto-generated by openapi-typescript.\n"
    " * Do not make direct changes to the file.\n"
    " */\n"
)

_HELPERS = """type _S = components["schemas"];
type _O = operations;
type _H = { [name: string]: unknown };
type _Empty = { headers: _H; content?: never };
type _J<T> = { headers: _H; content: { "application/json": T } };
type _B<T> = { content: { "application/json": T } };
type _LR<T> = { items: T[]; total: number };
type _NP = { query?: never; header?: never; path?: never; cookie?: never };
type _QP<Q> = { query?: Q; header?: never; path?: never; cookie?: never };
type _QPR<Q> = { query: Q; header?: never; path?: never; cookie?: never };
type _PP<P> = { query?: never; header?: never; path: P; cookie?: never };
type _PQP<P, Q> = { query?: Q; header?: never; path: P; cookie?: never };
type _E = _J<_S["ErrorResponse"]>;
type _VE = _J<_S["HTTPValidationError"]>;
type _Err = { 400: _E; 401: _E; 403: _E; 404: _E; 409: _E; 429: _E; 500: _E };
type _ErrV = _Err & { 422: _VE };
type _R<T, K extends number = 200> = Record<K, _J<T>> & _ErrV;
type _RN<T, K extends number = 200> = Record<K, _J<T>> & _Err;
type _R204 = { 204: _Empty } & _ErrV;
type _Op<Res, Params = _NP, Body = never, K extends number = 200> = {
  parameters: Params;
  responses: _R<Res, K>;
} & ([Body] extends [never] ? { requestBody?: never } : { requestBody: _B<Body> });
type _OpN<Res, Params = _NP, K extends number = 200> = {
  parameters: Params;
  requestBody?: never;
  responses: _RN<Res, K>;
};
type _M = "get" | "put" | "post" | "delete" | "options" | "head" | "patch" | "trace";
type _P<T> = { parameters: _NP } & T & Partial<Record<Exclude<_M, keyof T>, never>>;
"""


def _compact_snippets(content: str) -> str:
    content = re.sub(
        r"headers:\s*\{\s*\[name:\s*string\]:\s*unknown;\s*\};",
        "headers: { [name: string]: unknown; };",
        content,
    )
    content = re.sub(
        r"parameters:\s*\{\s*query\?:\s*never;\s*header\?:\s*never;\s*path\?:\s*never;\s*cookie\?:\s*never;\s*\};",
        "parameters: { query?: never; header?: never; path?: never; cookie?: never; };",
        content,
    )
    content = re.sub(
        r'(\d+):\s*\{\s*headers:\s*\{\s*\[name:\s*string\]:\s*unknown;\s*\};\s*content:\s*\{\s*"application/json":\s*([^;]+);\s*\};\s*\};',
        r'\1: { headers: { [name: string]: unknown; }; content: { "application/json": \2; }; };',
        content,
    )
    content = re.sub(
        r'(\d+):\s*\{\s*content:\s*\{\s*"application/json":\s*([^;]+);\s*\};\s*\};',
        r'\1: { content: { "application/json": \2; }; };',
        content,
    )
    content = re.sub(
        r"(\d+):\s*\{\s*headers:\s*\{\s*\[name:\s*string\]:\s*unknown;\s*\};\s*content\?:\s*never;\s*\};",
        r"\1: { headers: { [name: string]: unknown; }; content?: never; };",
        content,
    )

    def _join_never_lines(m: re.Match[str]) -> str:
        lines = [line.strip() for line in m.group(1).splitlines() if line.strip()]
        indent = m.group(1)[: len(m.group(1)) - len(m.group(1).lstrip())]
        return indent + " ".join(lines) + "\n"

    content = re.sub(
        r"((?:^[ \t]*(?:get|post|put|delete|options|head|patch|trace)\?:\s*never;\r?\n){2,})",
        _join_never_lines,
        content,
        flags=re.MULTILINE,
    )
    content = re.sub(
        r"((?:^[ \t]*(?:header|path|cookie)\?:\s*never;\r?\n){2,})",
        _join_never_lines,
        content,
        flags=re.MULTILINE,
    )
    return content


def _compact_path_block(match: re.Match[str]) -> str:
    path_lit, body = match.group(1), match.group(2)
    methods = re.findall(
        r'\b(get|put|post|delete|options|head|patch|trace):\s*(_O\["[^"]+"\]);', body
    )
    if methods and "parameters: _NP;" in body:
        inner = "; ".join(f"{k}: {v}" for k, v in methods)
        return f'    "{path_lit}": _P<{{ {inner} }}>;'
    return match.group(0)


def compact_api_types(content: str) -> str:
    if 'type _S = components["schemas"];' in content:
        return content
    if "export interface components" not in content:
        return _compact_snippets(content)

    s = re.sub(r"/\*\*[\s\S]*?\*/\s*", "", content)
    s = _compact_snippets(s)
    s = s.replace('components["schemas"]', "_S")
    s = s.replace("operations[", "_O[")
    s = re.sub(
        r'\{\s*headers:\s*\{\s*\[name:\s*string\]:\s*unknown;\s*\};\s*content:\s*\{\s*"application/json":\s*([^;]+);\s*\};\s*\}',
        r"_J<\1>",
        s,
    )
    s = re.sub(
        r"\{\s*headers:\s*\{\s*\[name:\s*string\]:\s*unknown;\s*\};\s*content\?:\s*never;\s*\}",
        "_Empty",
        s,
    )
    s = s.replace('_J<_S["ErrorResponse"]>', "_E")
    s = s.replace('_J<_S["HTTPValidationError"]>', "_VE")
    s = s.replace(
        "parameters: { query?: never; header?: never; path?: never; cookie?: never; };",
        "parameters: _NP;",
    )
    s = s.replace("headers: { [name: string]: unknown; };", "headers: _H;")
    s = re.sub(
        r"parameters:\s*\{\s*query(\??):\s*(\{[^{}]*\});\s*header\?:\s*never;\s*path\?:\s*never;\s*cookie\?:\s*never;\s*\};",
        lambda m: f"parameters: _QP<{m.group(2)}>;"
        if m.group(1) == "?"
        else f"parameters: _QPR<{m.group(2)}>;",
        s,
    )
    s = re.sub(
        r"parameters:\s*\{\s*query\?:\s*never;\s*header\?:\s*never;\s*path:\s*(\{[^{}]*\});\s*cookie\?:\s*never;\s*\};",
        r"parameters: _PP<\1>;",
        s,
    )
    s = re.sub(
        r"parameters:\s*\{\s*query\?:\s*(\{[^{}]*\});\s*header\?:\s*never;\s*path:\s*(\{[^{}]*\});\s*cookie\?:\s*never;\s*\};",
        r"parameters: _PQP<\2, \1>;",
        s,
    )
    s = re.sub(
        r'requestBody:\s*\{\s*content:\s*\{\s*"application/json":\s*([^;]+);\s*\};\s*\};',
        r"requestBody: _B<\1>;",
        s,
    )
    s = re.sub(
        r'requestBody\?:\s*\{\s*content:\s*\{\s*"application/json":\s*([^;]+);\s*\};\s*\};',
        r"requestBody?: _B<\1>;",
        s,
    )
    s = re.sub(
        r"responses:\s*\{\s*(20\d):\s*_J<([^>]+)>;\s*400:\s*_E;\s*401:\s*_E;\s*403:\s*_E;\s*404:\s*_E;\s*409:\s*_E;\s*422:\s*_VE;\s*429:\s*_E;\s*500:\s*_E;\s*\};",
        lambda m: f"responses: _R<{m.group(2)}>;"
        if m.group(1) == "200"
        else f"responses: _R<{m.group(2)}, {m.group(1)}>;",
        s,
    )
    s = re.sub(
        r"responses:\s*\{\s*(20\d):\s*_J<([^>]+)>;\s*400:\s*_E;\s*401:\s*_E;\s*403:\s*_E;\s*404:\s*_E;\s*409:\s*_E;\s*429:\s*_E;\s*500:\s*_E;\s*\};",
        lambda m: f"responses: _RN<{m.group(2)}>;"
        if m.group(1) == "200"
        else f"responses: _RN<{m.group(2)}, {m.group(1)}>;",
        s,
    )
    s = re.sub(
        r"responses:\s*\{\s*204:\s*_Empty;\s*400:\s*_E;\s*401:\s*_E;\s*403:\s*_E;\s*404:\s*_E;\s*409:\s*_E;\s*422:\s*_VE;\s*429:\s*_E;\s*500:\s*_E;\s*\};",
        "responses: _R204;",
        s,
    )
    s = re.sub(
        r"(\bListResponse_[A-Za-z0-9_]+):\s*\{\s*items:\s*([^;]+)\[\];\s*total:\s*number;\s*\};",
        r"\1: _LR<\2>;",
        s,
    )

    # Compact standard operations into _Op / _OpN
    def _fmt_op_no_body(m: re.Match[str]) -> str:
        op, params, res, status = m.group(1), m.group(2), m.group(3), m.group(4)
        if params == "_NP" and not status:
            return f"{op}: _Op<{res}>;"
        if not status:
            return f"{op}: _Op<{res}, {params}>;"
        return f"{op}: _Op<{res}, {params}, never, {status}>;"

    s = re.sub(
        r"(\b[A-Za-z0-9_]+):\s*\{\s*parameters:\s*([^;]+);\s*requestBody\?:\s*never;\s*responses:\s*_R<([^,>]+)(?:,\s*(\d+))?>;\s*\};",
        _fmt_op_no_body,
        s,
    )
    s = re.sub(
        r"(\b[A-Za-z0-9_]+):\s*\{\s*parameters:\s*([^;]+);\s*requestBody:\s*_B<([^>]+)>;\s*responses:\s*_R<([^,>]+)(?:,\s*(\d+))?>;\s*\};",
        lambda m: f"{m.group(1)}: _Op<{m.group(4)}, {m.group(2)}, {m.group(3)}>{';' if not m.group(5) else ''}"
        if not m.group(5)
        else f"{m.group(1)}: _Op<{m.group(4)}, {m.group(2)}, {m.group(3)}, {m.group(5)}>;",
        s,
    )
    s = re.sub(
        r"(\b[A-Za-z0-9_]+):\s*\{\s*parameters:\s*([^;]+);\s*requestBody\?:\s*never;\s*responses:\s*_RN<([^,>]+)(?:,\s*(\d+))?>;\s*\};",
        lambda m: f"{m.group(1)}: _OpN<{m.group(3)}>;"
        if m.group(2) == "_NP" and not m.group(4)
        else (
            f"{m.group(1)}: _OpN<{m.group(3)}, {m.group(2)}>;"
            if not m.group(4)
            else f"{m.group(1)}: _OpN<{m.group(3)}, {m.group(2)}, {m.group(4)}>;"
        ),
        s,
    )
    s = re.sub(
        r'^[ \t]*"([^"]+)":\s*\{([^{}]*)\};', _compact_path_block, s, flags=re.MULTILINE
    )
    s = re.sub(
        r"^( +)",
        lambda m: " " * max(2, len(m.group(1)) // 2)
        if len(m.group(1)) >= 4
        else m.group(1),
        s,
        flags=re.MULTILINE,
    )
    return _BANNER + _HELPERS + "\n" + s.lstrip()


def main(argv: Sequence[str] | None = None) -> int:
    args = list(argv) if argv is not None else sys.argv[1:]
    if not args:
        print("Usage: compact_api_types.py <path-to-api-types.ts>", file=sys.stderr)
        return 1

    target = Path(args[0])
    if not target.exists():
        print(f"Error: {target} does not exist", file=sys.stderr)
        return 1

    raw = target.read_text(encoding="utf-8")
    compacted = compact_api_types(raw)
    target.write_text(compacted, encoding="utf-8")
    print(
        f"Compacted {target}: {len(raw.splitlines())} -> {len(compacted.splitlines())} lines"
    )
    return 0
